export function createPerformanceHUD({renderer,world}){
 const panel=document.createElement('div');panel.id='performance';panel.setAttribute('role','status');panel.style.cssText='display:none;position:fixed;left:24px;bottom:58px;z-index:30;background:#13252de8;color:#e5efd6;padding:10px 14px;font:12px/1.6 monospace;white-space:pre;pointer-events:none';document.body.append(panel);let visible=false,elapsed=0,frames=0,next=0;
 addEventListener('keydown',e=>{if(e.key.toLowerCase()==='p'&&!e.repeat&&!e.target.matches('input,select,textarea')){visible=!visible;panel.style.display=visible?'block':'none'}});
 return{update(dt){if(document.hidden||dt>.5)return;elapsed+=dt;frames++;const now=performance.now();if(now<next)return;next=now+1000;const fps=frames/Math.max(.001,elapsed),terrain=world.terrain.stats,region=world.region.stats;panel.textContent=`${fps.toFixed(0)} FPS · ${(elapsed/Math.max(1,frames)*1000).toFixed(1)} ms/frame\n${renderer.info.render.calls} draws · ${(renderer.info.render.triangles/1000).toFixed(0)}k triangles\nTerrain ${terrain.tiles} tiles · ${terrain.queued} queued\nGround photos ${world.groundDetail?.stats.loaded||0} tiles\nScenery ${region.loaded} chunks · ${region.photos} roof photos\nTraffic ${world.traffic?.stats.moving||0} vehicles · ${world.traffic?.stats.nearby||0} nearby\nControls ${world.traffic?.stats.junctions||0} junctions · ${world.intersections?.stats.signals||0} signal approaches\nPeople ${world.people?.stats.walkers||0} walkers\nStreet furniture ${world.furniture?.stats.poles||0} poles · ${world.furniture?.stats.signs||0} signs · ${world.furniture?.stats.services||0} house leads\nUtilities ${world.furniture?.stats.utilities||0} cabinets / covers\nP · hide performance`;elapsed=0;frames=0}};
}
